// Arma el aviso a partir de lo que entrega el Error Trigger (flujo, ejecución, nodo y mensaje del error).
const x = $input.first().json;
const flujo = x.workflow?.name || 'Flujo sin nombre';
const ej = x.execution || {};
const err = ej.error || x.trigger?.error || {};
const nodo = ej.lastNodeExecuted || err.node?.name || 'desconocido';
const mensaje = err.message || 'Sin mensaje de error';
const cuando = new Intl.DateTimeFormat('es-CO', { timeZone: 'America/Bogota', dateStyle: 'medium', timeStyle: 'short' }).format(new Date());
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const enlace = ej.url ? `<p><a href="${esc(ej.url)}">Ver la ejecución en n8n</a></p>` : '<p>El error ocurrió en el disparador, antes de crear una ejecución.</p>';
const pila = err.stack ? `<pre style="white-space:pre-wrap;font-size:12px;color:#555">${esc(String(err.stack).slice(0, 2000))}</pre>` : '';
return [{ json: { correo: {
  sender: { name: 'n8n WIP', email: 'comercial@wiptool.com' },
  to: [{ email: 'jessica@wiptool.com' }],
  subject: `Falló ${flujo} (nodo: ${nodo})`,
  htmlContent: `<p><b>Flujo:</b> ${esc(flujo)}<br><b>Nodo:</b> ${esc(nodo)}<br><b>Cuándo:</b> ${cuando} (hora Colombia)<br><b>Modo:</b> ${esc(ej.mode || 'n/d')}</p><p><b>Error:</b> ${esc(mensaje)}</p>${enlace}${pila}`,
} } }];
